def nx_dinic_value(G,s,t):
    # map nodes actually present
    idx={}
    def gi(x):
        z=idx.get(x)
        if z is None:
            z=len(idx);idx[x]=z
        return z
    # First pass over edges, collect finite total for a safe infinity.
    total_finite=0
    for u,adj in G._adj.items():
        for v,data in adj.items():
            c=data.get('capacity')
            if c is not None:
                total_finite += c
    INF=total_finite+1 if total_finite>=0 else 1
    if INF<=0: INF=1
    # Also ensure INF big enough for common values? total finite includes H/temp caps.
    n=0
    # We'll build edge arrays. Need allocate nodes lazily.
    to=[];cap=[];nxtadj=None
    adjlist=[]
    def ensure(x):
        nonlocal n
        i=gi(x)
        while len(adjlist)<=i: adjlist.append([])
        if i+1>n:n=i+1
        return i
    def add(u,v,c):
        ui=ensure(u);vi=ensure(v)
        e=len(to);to.append(vi);cap.append(c);adjlist[ui].append(e)
        e2=len(to);to.append(ui);cap.append(0);adjlist[vi].append(e2)
    for u,adj in G._adj.items():
        for v,data in adj.items():
            c=data.get('capacity')
            if c is None: c=INF
            if c is not None and c>0:
                add(u,v,c)
    si=gi(s);ti=gi(t)
    while len(adjlist)<n:adjlist.append([])
    # Dinic
    from collections import deque
    level=[-1]*n;it=[0]*n
    flow=0
    N=n
    def bfs():
        for i in range(N):level[i]=-1
        level[si]=0;q=deque([si])
        while q:
            v=q.popleft();lv=level[v]+1
            for e in adjlist[v]:
                if cap[e]>0:
                    w=to[e]
                    if level[w]<0:
                        level[w]=lv
                        if w==ti:
                            # continue to build enough levels? can return early? full levels may not needed
                            pass
                        q.append(w)
        return level[ti]>=0
    sys_set=False
    import sys
    oldlim=sys.getrecursionlimit()
    if oldlim<10000:
        sys.setrecursionlimit(10000)
    def dfs(v,f):
        if v==ti:return f
        av=adjlist[v];i=it[v]
        while i<len(av):
            e=av[i]
            w=to[e]
            if cap[e]>0 and level[w]==level[v]+1:
                ret=dfs(w, f if f<cap[e] else cap[e])
                if ret:
                    cap[e]-=ret;cap[e^1]+=ret
                    it[v]=i
                    return ret
            i+=1;it[v]=i
        return 0
    while bfs():
        for i in range(N):it[i]=0
        while True:
            f=dfs(si,INF)
            if not f:break
            flow+=f
            if flow>=INF: break
    if oldlim<10000:sys.setrecursionlimit(oldlim)
    return flow
